const end = $now.setZone('Europe/Moscow').startOf('second');
const start = end.minus({ days: 7 });
const startUtc = start.toUTC().toISO({ suppressMilliseconds: true });
const endUtc = end.toUTC().toISO({ suppressMilliseconds: true });
const range = startUtc + '..' + endUtc;
const repo = 'BoYarin0805/n8n-review-test';
const query = 'repo:' + repo + ' is:issue ';

const metrics = [
  { key: 'opened', node: 'New issues', label: 'Новые', query: query + 'created:' + range },
  { key: 'closed', node: 'Closed issues', label: 'Закрытые', query: query + 'is:closed closed:' + range },
  { key: 'active', node: 'Updated open issues', label: 'Обновлённые открытые', query: query + 'is:open updated:' + range },
  { key: 'unlabeled', node: 'New unlabeled issues', label: 'Новые без лейблов', query: query + 'no:label created:' + range },
];

return [{
  json: {
    repo,
    from: start.toFormat('dd.MM.yyyy HH:mm'),
    to: end.toFormat('dd.MM.yyyy HH:mm'),
    from_iso: startUtc,
    to_iso: endUtc,
    week_key: end.startOf('week').toISODate(),
    previous_week_key: end.startOf('week').minus({ weeks: 1 }).toISODate(),
    metrics,
  },
}];

const window = $('Report window').first().json;
const knownTypes = ['bug', 'task', 'feature', 'needs-triage'];
const values = {};

for (const metric of window.metrics) {
  const pages = $(metric.node).all().flatMap(({ json }) => {
    const body = json.body ?? json;
    return Array.isArray(body) ? body : [body];
  });

  if (!pages.length || pages.some(page => !Array.isArray(page.items) || !Number.isInteger(page.total_count))) {
    throw new Error('Unexpected GitHub response for ' + metric.node);
  }

  const observed = new Map();
  for (const page of pages) {
    for (const issue of page.items) {
      observed.set(issue.id, issue);
    }
  }

  const byType = Object.fromEntries([...knownTypes, 'unclassified'].map(type => [type, 0]));
  const byAuthor = new Map();
  for (const issue of observed.values()) {
    const labels = (issue.labels ?? []).map(label =>
      (typeof label === 'string' ? label : label.name)?.toLowerCase()
    );
    const type = knownTypes.find(name => labels.includes(name)) ?? 'unclassified';
    const author = issue.user?.login ?? 'unknown';
    byType[type] += 1;
    byAuthor.set(author, (byAuthor.get(author) ?? 0) + 1);
  }

  const total = pages[0].total_count;
  values[metric.key] = {
    total,
    observed: observed.size,
    complete: observed.size === total && !pages.some(page => page.incomplete_results),
    byType,
    byAuthor: Object.fromEntries(byAuthor),
  };
}

return [{
  json: {
    week_key: window.week_key,
    previous_week_key: window.previous_week_key,
    metrics: values,
  },
}];

const window = $('Report window').first().json;
const current = $('Group by type and author').first().json.metrics;
const priorRow = $input.first().json;
const previous = priorRow.stats_json ? JSON.parse(priorRow.stats_json).metrics : null;
const summary = window.metrics.map(metric => {
  const currentMetric = current[metric.key];
  const previousTotal = previous?.[metric.key]?.total;
  const prior = Number.isInteger(previousTotal) && previousTotal >= 0 ? previousTotal : null;
  return {
    key: metric.key,
    label: metric.label,
    current: currentMetric.total,
    previous: prior,
    delta: prior === null ? null : currentMetric.total - prior,
    complete: currentMetric.complete,
  };
});

return [{
  json: {
    ...window,
    current,
    summary,
    stats_json: JSON.stringify({
      from: window.from_iso,
      to: window.to_iso,
      metrics: current,
    }),
  },
}];

const report = $('Compare weeks').first().json;
const answer = $input.first().json;
const aiComment = answer.text ?? answer.output;
if (typeof aiComment !== 'string' || !aiComment.trim()) {
  throw new Error('The AI summary returned no text');
}

function safe(value) {
  const characters = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(value).replace(/[&<>"']/g, char => characters[char]);
}

const cellStyle = 'border:1px solid #ddd;padding:6px 10px;text-align:left';
function table(headers, rows) {
  const head = headers.map(value => '<th style="' + cellStyle + '">' + safe(value) + '</th>').join('');
  const body = rows.map(row => {
    const cells = row.map(value => '<td style="' + cellStyle + '">' + safe(value) + '</td>').join('');
    return '<tr>' + cells + '</tr>';
  }).join('');
  return '<table style="border-collapse:collapse"><thead><tr>' + head + '</tr></thead><tbody>' + body + '</tbody></table>';
}

function showDelta(delta) {
  if (delta === null) return '—';
  return delta > 0 ? '+' + delta : String(delta);
}

const totals = report.summary.map(metric => [
  metric.label, metric.current, metric.previous ?? '—', showDelta(metric.delta),
]);
const types = ['bug', 'task', 'feature', 'needs-triage', 'unclassified'];
const byType = report.metrics.map(metric => [
  metric.label,
  ...types.map(type => report.current[metric.key].byType[type]),
]);

const authors = new Set(report.metrics.flatMap(metric => Object.keys(report.current[metric.key].byAuthor)));
const authorRows = [...authors].map(author => [
  author,
  ...report.metrics.map(metric => report.current[metric.key].byAuthor[author] ?? 0),
]);
const sum = row => row.slice(1).reduce((total, count) => total + count, 0);
authorRows.sort((left, right) => sum(right) - sum(left) || left[0].localeCompare(right[0]));

const limitations = report.metrics
  .filter(metric => !report.current[metric.key].complete)
  .map(metric => {
    const data = report.current[metric.key];
    return '<p>' + safe(metric.label) + '. Разбивка по типам и авторам включает '
      + safe(data.observed) + ' из ' + safe(data.total) + ' результатов поиска.</p>';
  })
  .join('');

const html = [
  '<div style="font-family:Arial,sans-serif;color:#202124;line-height:1.45">',
  '<h1>Еженедельный отчёт по GitHub Issues</h1>',
  '<p>' + safe(report.repo) + ' · ' + safe(report.from) + ' — ' + safe(report.to) + ' (МСК)</p>',
  '<h2>Статистика и изменение за неделю</h2>',
  table(['Показатель', 'Текущий период', 'Предыдущий период', 'Δ'], totals),
  '<h2>По типам</h2>',
  table(['Показатель', 'bug', 'task', 'feature', 'needs-triage', 'Без типа'], byType),
  '<h2>По авторам</h2>',
  authorRows.length
    ? table(['Автор', ...report.metrics.map(metric => metric.label)], authorRows.slice(0, 20))
    : '<p>Учитываемых обращений за период нет.</p>',
  authorRows.length > 20 ? '<p>Показаны 20 наиболее активных авторов.</p>' : '',
  limitations,
  '<h2>AI-комментарий недели</h2>',
  '<p>' + safe(aiComment.trim()).replace(/\r?\n/g, '<br>') + '</p>',
  '</div>',
].join('');

return [{
  json: {
    subject: 'GitHub Issues · ' + report.repo + ' · ' + report.to.slice(0, 10),
    html,
  },
}];
